  "type": "object",
  "properties": {
    "content": {
      "description": "The message content expression.",
      "$ref": "functions.expression.WithExpression.agent.completions.message.SimpleContentExpression"
    },
    "name": {
      "description": "Optional name expression.",
      "anyOf": [
        {
